('soldier-pay', '봉급(병사)', array['병사 월급', '병장 월급', '이병 월급', '일병 월급', '상병 월급', '병 봉급', '월급']::text[], '기본급여', array['soldier']::text[], '의무복무 병사에게 계급별로 매월 정액 지급되는 봉급입니다.', '이병 75만 원 · 일병 90만 원 · 상병 120만 원 · 병장 150만 원 (월)', '[{"label":"이병","value":"75만 원"},{"label":"일병","value":"90만 원"},{"label":"상병","value":"120만 원"},{"label":"병장","value":"150만 원"}]'::jsonb, false, array['현역 병사(이병~병장)']::text[], array['신청 없이 매월 자동 지급됩니다.']::text[], '{}'::text[], array['2026년 병사 봉급은 2025년과 같은 금액으로 유지되었습니다.']::text[], '[{"title":"공무원보수규정","article":"별표 13 비고(병사 월지급액)","url":"https://www.law.go.kr/법령/공무원보수규정"}]'::jsonb, '2026-11-20', false),
('officer-pay', '봉급(간부)', array['간부 월급', '부사관 월급', '장교 월급', '호봉', '봉급표', '기본급']::text[], '기본급여', array['officer']::text[], '직업군인에게 계급과 호봉에 따라 매월 지급되는 기본급입니다.', '계급·호봉별 봉급표에 따름. 2026년 하사·중사·소위·중위 등 초급간부는 추가 인상', null, false, array['장교, 준사관, 부사관']::text[], array['신청 없이 매월 자동 지급됩니다.', '호봉 확인은 소속 부대 인사·급여 담당에게 문의하세요.']::text[], '{}'::text[], array['실제 월급은 봉급에 정근수당, 가족수당 등 각종 수당이 더해진 금액입니다.']::text[], '[{"title":"공무원보수규정","article":"별표 13 군인의 봉급표","url":"https://www.law.go.kr/법령/공무원보수규정"}]'::jsonb, '2026-11-20', false),
('civilian-pay', '봉급(군무원)', array['군무원 월급', '군무원 호봉']::text[], '기본급여', array['civilian']::text[], '군무원에게 급수와 호봉에 따라 매월 지급되는 기본급입니다.', '급수·호봉별 군무원 봉급표에 따름', null, false, array['군무원']::text[], array['신청 없이 매월 자동 지급됩니다.']::text[], '{}'::text[], '{}'::text[], '[{"title":"공무원보수규정","article":"군무원 봉급표","url":"https://www.law.go.kr/법령/공무원보수규정"}]'::jsonb, '2026-11-20', false),
('soldier-savings-match', '장병내일준비적금 매칭지원금', array['내일준비적금', '장병적금', '적금', '매칭', '매칭지원금', '전역 목돈']::text[], '병사 지원', array['soldier']::text[], '병사가 장병내일준비적금에 넣은 금액만큼 정부가 추가로 지원해 전역 때 함께 받는 제도입니다.', '본인 납입액의 100% 매칭, 월 납입 한도 55만 원. 전역 시 원금·이자와 함께 일괄 지급', null, true, array['현역 병사(가입해야 받을 수 있음)']::text[], array['취급 은행 앱이나 영업점에서 장병내일준비적금에 가입합니다.', '입대 후 빨리 가입할수록 매칭받는 기간이 길어집니다(가입 전 기간은 소급되지 않음).']::text[], array['신분 확인(나라사랑카드 등) — 은행 안내 확인']::text[], array['법정 수당은 아니며, 복무 중 매월 통장에 들어오는 돈이 아니라 전역 때 받습니다.']::text[], '[{"title":"국방부 장병내일준비적금 안내"}]'::jsonb, '2026-11-20', false),
('longevity-pay', '정근수당', array['정근', '1월 7월 수당', '상여금']::text[], '상여수당', array['officer', 'civilian']::text[], '근무연수에 따라 1년에 두 번(1월·7월) 지급되는 상여 성격의 수당입니다.', '근무연수별 월봉급액의 10~50%, 연 2회(1월·7월)', null, false, array['지급 기준일 현재 재직 중인 간부·군무원']::text[], array['신청 없이 1월·7월 급여에 포함되어 지급됩니다.']::text[], '{}'::text[], array['징계·휴직 등으로 감액될 수 있습니다.']::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정"},{"title":"인사혁신처 공무원 보수체계 안내","url":"https://www.mpm.go.kr/mpm/info/resultPay/bizPay01"}]'::jsonb, '2026-11-20', false),
('longevity-addition', '정근수당 가산금', array['정근가산금', '가산금']::text[], '상여수당', array['officer', 'civilian']::text[], '근무연수 5년 이상부터 매월 정액으로 더해지는 수당입니다.', '근무연수별 월 정액 (인사혁신처 안내 기준 월 3만~13만 원)', null, false, array['근무연수 5년 이상 간부·군무원']::text[], array['신청 없이 매월 자동 지급됩니다.']::text[], '{}'::text[], array['근무연수 구간별 금액은 규정 별표 2로 확인하세요.']::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정","article":"별표 2"}]'::jsonb, '2026-11-20', true),
('performance-bonus', '성과상여금', array['성과급', '성과금']::text[], '상여수당', array['officer', 'civilian']::text[], '근무 성적 평가 등급에 따라 1년에 한 번 이상 지급되는 상여금입니다.', '평가 등급별 지급기준액의 0~172.5%, 연 1회 이상', null, false, array['평가 대상 기간 중 일정 기간 이상 근무한 간부·군무원']::text[], array['평가 결과에 따라 자동 지급됩니다.']::text[], '{}'::text[], '{}'::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정"},{"title":"인사혁신처 공무원 보수체계 안내","url":"https://www.mpm.go.kr/mpm/info/resultPay/bizPay01"}]'::jsonb, '2026-11-20', false),
('senior-treatment', '대우공무원수당', array['대우공무원']::text[], '상여수당', array['civilian']::text[], '상위 직급 대우공무원으로 선발된 군무원에게 지급되는 수당입니다.', '월봉급액의 4.1%', null, false, array['군무원인사법 시행령에 따라 대우공무원으로 선발된 군무원']::text[], array['선발되면 자동 지급됩니다.']::text[], '{}'::text[], '{}'::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정","article":"제6조의2"}]'::jsonb, '2026-11-20', false),
