('parental-leave', '육아휴직수당', array['육아휴직', '육휴', '휴직']::text[], '가계보전', array['officer', 'civilian']::text[], '자녀 양육을 위해 육아휴직한 간부·군무원에게 지급되는 수당입니다.', '휴직 기간별 월봉급액의 일정 비율(상한액 있음). 휴직 초기 몇 달은 100%', null, true, array['자녀 양육을 위해 육아휴직한 간부·군무원 (자녀 연령 기준은 규정 확인)']::text[], array['육아휴직 신청 시 수당 신청을 함께 합니다.']::text[], array['육아휴직 명령서', '가족관계증명서']::text[], array['기간별 비율과 상한액은 자주 바뀌니 신청 전 최신 기준을 확인하세요.']::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정"}]'::jsonb, '2026-11-20', true),
