('hazard-duty', '위험근무수당', array['위험수당', '공수', '강하', '낙하산', 'UDT', 'SSU', '불발탄', 'EOD', '잠수', '특전']::text[], '특수근무', array['officer', 'soldier']::text[], '낙하산 강하, 수중 파괴, 불발탄 처리 등 위험한 직무를 하는 군인에게 지급되는 수당입니다.', '직무별 갑·을·병종 등급에 따라 지급 (하사 이하는 장기하사 최저호봉 봉급 기준)', null, false, array['규정 별표 10에 정한 위험 직무에 종사하는 군인']::text[], array['해당 직무 명령이 있으면 부대에서 지급 처리합니다.']::text[], '{}'::text[], array['직무별 세부 금액은 「군인 등의 특수근무수당에 관한 규칙」 별표 1을 확인하세요.']::text[], '[{"title":"공무원수당 등에 관한 규정","url":"https://www.law.go.kr/법령/공무원수당등에관한규정","article":"제13조, 별표 10"},{"title":"군인 등의 특수근무수당에 관한 규칙","url":"https://www.law.go.kr/법령/군인등의특수근무수당에관한규칙"}]'::jsonb, '2026-11-20', true),
